const TARGET_URL = 'https://efuturemedia.app.n8n.cloud/webhook/lokalise-to-review';
const EVENTS = ['project.key.added', 'project.translation.updated'];
const ONLY_PROJECT_IDS = [];
const projects = $('Split Out Projects').all();
const rows = $input.all();
const out = [];
for (let i = 0; i < rows.length; i++) {
  const p = (projects[i] && projects[i].json) || {};
  const j = rows[i].json || {};
  const hooks = j.webhooks || j.data || [];
  const checkFailed = !!j.error;
  const inScope = ONLY_PROJECT_IDS.length === 0 || ONLY_PROJECT_IDS.indexOf(p.project_id) !== -1;
  let existing = null;
  for (const h of hooks) {
    if (String(h.url || '') === TARGET_URL) { existing = h; break; }
  }
  const currentEvents = existing && Array.isArray(existing.events) ? existing.events : [];
  const missingEvents = EVENTS.filter((e) => currentEvents.indexOf(e) === -1);
  out.push({ json: {
    projectId: p.project_id || '',
    projectName: p.name || '',
    baseLanguage: p.base_language_iso || '',
    targetUrl: TARGET_URL,
    events: EVENTS,
    scopeLimitedTo: ONLY_PROJECT_IDS,
    inScope: inScope,
    webhookCount: hooks.length,
    existingWebhookId: existing ? existing.webhook_id : null,
    existingEvents: currentEvents,
    missingEvents: missingEvents,
    checkFailed: checkFailed,
    needsCreate: inScope && !checkFailed && !!p.project_id && !existing
  } });
}
return out;

const checked = $('Find Missing Webhooks').all().map((i) => i.json);
const targets = $('Only Projects Missing It').all().map((i) => i.json);
const results = $input.all().map((i) => i.json);
const created = [];
const failed = [];
for (let i = 0; i < targets.length; i++) {
  const r = results[i] || {};
  const label = targets[i].projectName + ' (' + targets[i].projectId + ')';
  if (r.error) {
    failed.push({ project: label, error: String((r.error && r.error.message) || r.error) });
  } else {
    const w = r.webhook || r;
    created.push({ project: label, webhookId: w.webhook_id || null });
  }
}
const scope = (checked[0] && checked[0].scopeLimitedTo) || [];
return [{ json: {
  scope: scope.length === 0 ? 'all projects' : scope,
  projectsSeen: checked.length,
  projectsInScope: checked.filter((p) => p.inScope).length,
  alreadyRegisteredInScope: checked.filter((p) => p.inScope && p.existingWebhookId).length,
  createdCount: created.length,
  failedCount: failed.length,
  createdIn: created,
  failures: failed,
  couldNotCheck: checked.filter((p) => p.checkFailed).map((p) => p.projectName),
  existingButMissingEvents: checked.filter((p) => p.existingWebhookId && p.missingEvents.length > 0).map((p) => ({ project: p.projectName, webhookId: p.existingWebhookId, missingEvents: p.missingEvents }))
} }];
